import { useState, useEffect } from 'react';
import styles from './SummaryCard.module.css';

const SummaryCard = ({ 
  totalIncome: propTotalIncome, 
  totalExpenses: propTotalExpenses, 
  balance: propBalance, 
  currentBalance: propCurrentBalance 
}) => {
  // Estado inicial cargado desde localStorage
  const [totalIncome, setTotalIncome] = useState(0);
  const [totalExpenses, setTotalExpenses] = useState(0);
  const [balance, setBalance] = useState(0);
  const [currentBalance, setCurrentBalance] = useState(0);

  // Cargar datos del localStorage al montar el componente
  useEffect(() => {
    const savedData = JSON.parse(localStorage.getItem('financialSummary')) || {};
    
    setTotalIncome(savedData.totalIncome || propTotalIncome || 0);
    setTotalExpenses(savedData.totalExpenses || propTotalExpenses || 0);
    setBalance(savedData.balance || propBalance || 0);
    setCurrentBalance(savedData.currentBalance || propCurrentBalance || 0);
  }, []);

  // Guardar en localStorage cuando las props cambien
  useEffect(() => {
    const financialData = {
      totalIncome: propTotalIncome !== undefined ? propTotalIncome : totalIncome,
      totalExpenses: propTotalExpenses !== undefined ? propTotalExpenses : totalExpenses,
      balance: propBalance !== undefined ? propBalance : balance,
      currentBalance: propCurrentBalance !== undefined ? propCurrentBalance : currentBalance
    };

    localStorage.setItem('financialSummary', JSON.stringify(financialData));

    // Actualizar estados internos si las props cambiaron
    if (propTotalIncome !== undefined) setTotalIncome(propTotalIncome);
    if (propTotalExpenses !== undefined) setTotalExpenses(propTotalExpenses);
    if (propBalance !== undefined) setBalance(propBalance);
    if (propCurrentBalance !== undefined) setCurrentBalance(propCurrentBalance);
  }, [propTotalIncome, propTotalExpenses, propBalance, propCurrentBalance]);

  return (
    <div className={styles.card}>
      <h3>Resumen Financiero</h3>
      <div className={styles.summaryItem}>
        <p>Ingresos: ${totalIncome}</p>
      </div>
      <div className={styles.summaryItem}>
        <p>Gastos: ${totalExpenses}</p>
      </div>
      <div className={styles.summaryItem}>
        <p>Balance: ${balance}</p>
      </div>
      <div className={styles.summaryItem}>
        <p>Saldo Actual: ${currentBalance}</p>
      </div>
    </div>
  );
};

export default SummaryCard;
